"""Legacy-compatible batch job error-handling runner."""

from collections.abc import Callable
from typing import Any


def run_jobs(
    jobs: list[dict],
    executor: Callable[[dict], Any],
) -> list[dict]:
    """Execute jobs sequentially using Meridian CRM batch failure semantics."""
    run_log: list[dict] = []

    for job in jobs:
        policy = job["on_error"]["policy"]
        max_attempts = (
            job["on_error"]["retries"] + 1
            if policy == "RETRY"
            else 1
        )
        attempts = 0

        while attempts < max_attempts:
            attempts += 1
            try:
                executor(job)
            except Exception:
                if policy == "RETRY" and attempts < max_attempts:
                    continue

                if policy == "CONTINUE":
                    run_log.append(
                        {
                            "name": job["name"],
                            "attempts": attempts,
                            "outcome": "skip",
                            "audits": ["BATCH_ROWSKIP"],
                        }
                    )
                    break

                run_log.append(
                    {
                        "name": job["name"],
                        "attempts": attempts,
                        "outcome": "abort",
                        "audits": [],
                    }
                )
                return run_log
            else:
                run_log.append(
                    {
                        "name": job["name"],
                        "attempts": attempts,
                        "outcome": "ok",
                        "audits": [],
                    }
                )
                break

    return run_log
